// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.lang.reflect.Method;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativePlanExecutionProfile.Mode;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

/** Tests intermediate helpers that must not erase an explicit or overflowed upper bound. */
class LmdbNativeUpperBoundPropagationTest {

	@Test
	void aggregateInputKeepsUnknownFeatureBoundsAndZeroFeaturesSeparate() {
		NativeAggregateCostQuotes.Input input = new NativeAggregateCostQuotes.Input(2D, 2D, 1D, 3D, 4D,
				0D, Double.POSITIVE_INFINITY, LmdbNativeCostVector.zero());
		LmdbNativeCostVector vector = input.operations();
		assertThat(vector.expected(Feature.INTERPRETED_ROW)).isEqualTo(3D);
		assertThat(vector.expected(Feature.DECODED_ROW)).isEqualTo(4D);
		assertThat(vector.high(Feature.INTERPRETED_ROW)).isPositive().isInfinite();
		assertThat(vector.high(Feature.DECODED_ROW)).isPositive().isInfinite();
		LmdbNativeCostVector zero = new NativeAggregateCostQuotes.Input(2D, 0D, 0D, 0D, 0D,
				0D, Double.POSITIVE_INFINITY, LmdbNativeCostVector.zero()).operations();
		assertThat(zero.isZero()).isTrue();
	}

	@Test
	void genericPremiumPreservesAnUnknownUnrelatedFeature() throws Exception {
		LmdbNativeCostVector unknown = LmdbNativeCostQuote.ofWork(LmdbNativeWork.UNKNOWN, Double.NaN)
				.total()
				.plus(LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, 1D));
		Method premium = LmdbNativePlanExecutionProfile.class.getDeclaredMethod("withPremium",
				LmdbNativeCostVector.class);
		premium.setAccessible(true);
		LmdbNativeCostVector actual = (LmdbNativeCostVector) premium.invoke(null, unknown);
		assertThat(actual.expected(Feature.INTERPRETED_ROW))
				.isEqualTo(LmdbNativePlanExecutionProfile.GENERIC_ROW_PREMIUM);
		assertThat(actual.high(Feature.SCANNED_ROW)).isPositive().isInfinite();
	}

	@Test
	void factorizedUnknownPrefixesKeepNamedCeilingsWithoutInfiniteNormalScales() {
		SlotPlan child = input(2D);
		LmdbNativeCostVectors.FactorizedRowsProfile profile = LmdbNativeCostVectors.factorizedRowsProfile(
				new SlotPlan[] { child, child, child }, 2,
				new LmdbNativeCostVectors.BranchRole[] { LmdbNativeCostVectors.BranchRole.ENUM },
				Double.NaN, null, 0L);
		assertThat(profile.emittedRows()).isEqualTo(8D);
		assertThat(profile.emittedRowsHigh()).isPositive().isInfinite();
		for (Feature feature : new Feature[] { Feature.SCANNED_ROW, Feature.DECODED_ROW, Feature.BATCH_ROW,
				Feature.HASH_PROBE, Feature.BRANCH_OPEN }) {
			assertThat(profile.vector().high(feature)).as("named ceiling %s", feature).isPositive().isInfinite();
			assertThat(profile.vector().expected(feature)).as("finite expectation %s", feature).isFinite();
		}
	}

	@ParameterizedTest
	@EnumSource(Mode.class)
	void overflowedExtensionWorkRemainsUnboundedInEveryTier(Mode mode) {
		ExtensionPlan extension = new ExtensionPlan(input(Double.MAX_VALUE),
				new CopyBinding[] { CopyBinding.constant(0, 1L), CopyBinding.constant(1, 2L) });
		LmdbNativeCostVector vector = LmdbNativePlanExecutionProfile.profile(extension, null, 0L, mode);
		assertThat(vector.expected(Feature.INTERPRETED_ROW)).isEqualTo(Double.MAX_VALUE);
		assertThat(vector.high(Feature.INTERPRETED_ROW)).isPositive().isInfinite();
		assertThat(LmdbNativeStaticPrior.DEFAULT.price(vector).known()).isFalse();
	}

	private static SlotPlan input(double rows) {
		SlotPlan plan = mock(SlotPlan.class);
		when(plan.estimateWork(null, 0L)).thenReturn(LmdbNativeWork.exact(1D));
		when(plan.estimateRows(null, 0L)).thenReturn(rows);
		return plan;
	}
}
